-- Slice 05: a monotonic insertion order for Apps. Runs once, as the owner of the database, like 0001_init.sql.
--
-- Listing Apps "newest first" tie-broke on the random App id when two Apps shared a millisecond, so the
-- order was not stable. A generated identity column counts up on every insert and gives the true creation
-- order. It is internal: it is never exposed in the API, only used to order the list.
--
-- GENERATED BY DEFAULT AS IDENTITY backfills existing rows in physical (insertion) order, and its implicit
-- sequence needs no separate grant: the table-level INSERT privilege already covers it.
ALTER TABLE apps ADD COLUMN seq bigint GENERATED BY DEFAULT AS IDENTITY;

CREATE INDEX apps_seq ON apps (organization_id, seq DESC);
